# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HABEŞİSTAN HİCRETİ (615 – 616): İSLAM\'DA İLK GÖÇ (PH.6.1.3)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Hicretin Sebebi ve Kafileler</text>\n  <text x="182" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Müşriklerin ilk Müslümanlara yönelik</text>\n  <text x="182" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">baskı ve işkencelerinin dayanılmaz</text>\n  <text x="182" y="134" text-anchor="middle" font-size="11" fill="#1e3a8a">boyuta ulaşması üzerine izin verildi.</text>\n  <text x="182" y="160" text-anchor="middle" font-size="11" fill="#1e3a8a">• I. Kafile (615): 11 erkek, 4 kadın (Hz. Osman</text>\n  <text x="182" y="178" text-anchor="middle" font-size="11" fill="#1e3a8a">ve eşi Hz. Rukiyye dâhil toplam 15 kişi).</text>\n  <text x="182" y="200" text-anchor="middle" font-size="11" fill="#1e3a8a">• II. Kafile (616): Cafer bin Ebû Tâlib</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">başkanlığında yaklaşık 100 sahabi.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Adil Hükümdar Necaşi ve Sonuç</text>\n  <text x="517" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Hz. Peygamber Habeşistan\'ı «Orada</text>\n  <text x="517" y="116" text-anchor="middle" font-size="11" fill="#14532d">kimseye zulmedilmeyen adil bir hükümdar</text>\n  <text x="517" y="134" text-anchor="middle" font-size="11" fill="#14532d">(Necaşi Ashame) vardır» diyerek seçti.</text>\n  <text x="517" y="160" text-anchor="middle" font-size="11" fill="#14532d">• Hz. Cafer, Necaşi huzurunda Meryem</text>\n  <text x="517" y="178" text-anchor="middle" font-size="11" fill="#14532d">suresinin ilk ayetlerini okudu.</text>\n  <text x="517" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">• Necaşi Müslümanları müşriklere</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">teslim etmedi ve himaye altına aldı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SOSYAL-EKONOMİK BOYKOT (616–619) VE HÜZÜN YILI (619)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Üç Yıllık Boykot (Muhasara)</text>\n  <text x="182" y="98" text-anchor="middle" font-size="11" fill="#713f12">• Hz. Hamza ve Hz. Ömer\'in Müslüman</text>\n  <text x="182" y="116" text-anchor="middle" font-size="11" fill="#713f12">olmasıyla paniğe kapılan müşrikler,</text>\n  <text x="182" y="134" text-anchor="middle" font-size="11" fill="#713f12">Haşimoğulları ile tüm ilişkiyi kesti:</text>\n  <text x="182" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">- Kız alıp verme ve evlilik yasaklandı.</text>\n  <text x="182" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">- Alışveriş ve gıda satışı yasaklandı.</text>\n  <text x="182" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">- Konuşma ve ziyaret yasaklandı.</text>\n  <text x="182" y="218" text-anchor="middle" font-size="10.5" fill="#713f12">Yer: Şi\'b-i Ebû Tâlib Mahallesi (3 Yıl)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Hüzün Yılı (Senetü\'l-Hüzün - 619)</text>\n  <text x="517" y="98" text-anchor="middle" font-size="11" fill="#9d174d">• Ağır boykot şartlarının bitiminden</text>\n  <text x="517" y="116" text-anchor="middle" font-size="11" fill="#9d174d">kısa süre sonra Peygamberimiz en büyük</text>\n  <text x="517" y="134" text-anchor="middle" font-size="11" fill="#9d174d">iki destekçisini art arda kaybetti:</text>\n  <text x="517" y="160" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be185d">1) Amcası Ebû Tâlib (Mekke\'deki hamisi)</text>\n  <text x="517" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be185d">2) Eşi Hz. Hatice (İlk inanan, sırdaşı)</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" fill="#9d174d">Ardından Taif yolculuğu ve İsra-Miraç</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE KRONOLOJİK ÖZETİ: GENÇLİK YILLARI VE İLK VAHİY SÜRECİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">1. Peygamberlik Öncesi Gençlik</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#155e75">• Çobanlık ve dürüst ticaret</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#155e75">• Ficar Savaşı ve Hilfü\'l-Fudûl</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#155e75">(Erdemliler Topluluğu - 20 yaş)</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#155e75">• Hz. Hatice ile evlilik (25 yaş)</text>\n  <text x="125" y="182" text-anchor="middle" font-size="11" fill="#155e75">• Kâbe Hakemliği (35 yaş)</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Unvanı: Muhammedü\'l-Emîn</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">2. Vahyin Gelişi ve Davet</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Hira Mağarası\'nda tefekkür ve</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">İnzivâ (Tahannüs) hayatı</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• İlk Vahiy: 610 Ramazan /</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">Alak suresi 1-5 («Oku!»)</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#1e3a8a">• İlk Müslümanlar: Hz. Hatice,</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#1e3a8a">Hz. Ali, Hz. Zeyd, Hz. Ebû Bekir</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Darü\'l-Erkam (Eğitim Merkezi)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Sabır ve Kararlılık Yılları</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#581c87">• Açık Davet: Safa Tepesi (613)</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#581c87">• Habeşistan Hicreti (615–616)</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11" fill="#581c87">• 3 Yıllık Boykot (616–619)</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11" fill="#581c87">• Hüzün Yılı ve Taif Yolculuğu</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" fill="#581c87">• Güneşi sağ elime, ayı sol</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">elime verseler davamdan dönmem!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
